package dev.arabicgames.tv;
import android.graphics.drawable.GradientDrawable;import android.widget.TextView;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class TvTextStyleTest {
 @Test public void TransparentTextDoesNotChangeSavedBackgroundOrPosition(){try(var c=Robolectric.buildActivity(MainActivity.class).setup()){var a=c.get();var p=a.getPreferences(0);p.edit().putInt("subtitleOpacity",65).putInt("subtitleTextMode",1).apply();ReflectionHelpers.callInstanceMethod(a,"applySubtitleStyle");TextView t=ReflectionHelpers.getField(a,"subtitle");assertEquals(0,((GradientDrawable)t.getBackground()).getColor().getDefaultColor());assertTrue(t.getShadowRadius()>0);p.edit().putInt("subtitleTextMode",2).apply();ReflectionHelpers.callInstanceMethod(a,"applySubtitleStyle");assertEquals(Math.round(65*255f/100)<<24,((GradientDrawable)t.getBackground()).getColor().getDefaultColor());assertEquals(65,p.getInt("subtitleOpacity",0));}}
 @Test public void TransparentSourceIsHonoredButLocalLegacyChoiceCanOverride(){try(var c=Robolectric.buildActivity(MainActivity.class).setup()){var a=c.get();a.getPreferences(0).edit().putInt("subtitleTextMode",0).apply();ReflectionHelpers.setField(a,"sourceTransparent",true);ReflectionHelpers.callInstanceMethod(a,"applySubtitleStyle");TextView t=ReflectionHelpers.getField(a,"subtitle");assertEquals(0,((GradientDrawable)t.getBackground()).getColor().getDefaultColor());a.getPreferences(0).edit().putInt("subtitleTextMode",2).apply();ReflectionHelpers.callInstanceMethod(a,"applySubtitleStyle");assertNotEquals(0,((GradientDrawable)t.getBackground()).getColor().getDefaultColor());}}
}
